import{_ as i,o as t,c as e,a2 as s}from"./chunks/framework.BqNd1sPY.js";const _=JSON.parse('{"title":"数字漫画：训练与验证是两套题","description":"","frontmatter":{},"headers":[],"relativePath":"04-图解与数字漫画/训练与验证-两套题.md","filePath":"04-图解与数字漫画/训练与验证-两套题.md"}'),r={name:"04-图解与数字漫画/训练与验证-两套题.md"};function o(l,a,n,d,m,c){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="数字漫画-训练与验证是两套题" tabindex="-1">数字漫画：训练与验证是两套题 <a class="header-anchor" href="#数字漫画-训练与验证是两套题" aria-label="Permalink to &quot;数字漫画：训练与验证是两套题&quot;">​</a></h1><h2 id="第一格-练习册" tabindex="-1">第一格：练习册 <a class="header-anchor" href="#第一格-练习册" aria-label="Permalink to &quot;第一格：练习册&quot;">​</a></h2><p>学生反复做训练题，训练 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 从 4 降到 1。</p><h2 id="第二格-陌生卷" tabindex="-1">第二格：陌生卷 <a class="header-anchor" href="#第二格-陌生卷" aria-label="Permalink to &quot;第二格：陌生卷&quot;">​</a></h2><p>老师拿出未参与训练的验证题，验证 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 从 4 降到 2，说明学到的模式对新样本也有帮助。</p><h2 id="第三格-背答案" tabindex="-1">第三格：背答案 <a class="header-anchor" href="#第三格-背答案" aria-label="Permalink to &quot;第三格：背答案&quot;">​</a></h2><p>继续练习后，训练 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 从 1 降到 0.2，验证 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 却从 2 升到 2.5。这是<a href="/LLMTrain/05-速查表/术语速查#term-overfitting" class="wiki-term" data-wiki-title="overfitting" data-wiki-summary="模型继续改善训练数据表现，却不能同步改善未见数据表现的现象。" data-wiki-misconception="训练 loss 下降就一定没有过拟合。">过拟合</a>信号之一。</p><h2 id="第四格-别偷看期末卷" tabindex="-1">第四格：别偷看期末卷 <a class="header-anchor" href="#第四格-别偷看期末卷" aria-label="Permalink to &quot;第四格：别偷看期末卷&quot;">​</a></h2><p>如果根据测试集反复改配置，测试集已经参与开发，不再是独立的最终检查。应保留新的测试集或明确报告开发过程。</p>',9)])])}const k=i(r,[["render",o]]);export{_ as __pageData,k as default};
